223	// FP32 vec4 apply: float4 traffic, canonical prodigy_apply_step CALLED 4×.
224	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
225	prodigy_apply_kernel_vec4_fp32(
226	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4, float4* s_track4,
227	    const float4* grad4, const float* d_ptr,
228	    float beta1, float beta2, float eps, float wd,
229	    float bc1, float bc2, int64_t N4
230	) {
231	    const float d = *d_ptr;
232	    const int64_t stride = prim::grid_stride();
233	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
234	        float4 p  = prim::ld_f32v4(param4 + i);
235	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
236	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
237	        float4 st = prim::ld_f32v4(s_track4 + i);
238	        float4 g  = prim::ldg_f32v4(grad4 + i);
239	        ::grokking::sm90::sg_sanitize_grad4(g);
240	        #pragma unroll
241	        for (int u = 0; u < 4; ++u) {
242	            prodigy_apply_step(&p.x, &m.x, &v.x, &st.x, &g.x,
243	                               d, beta1, beta2, eps, wd, bc1, bc2, u);
244	        }
245	        prim::st_f32v4(param4 + i, p);
246	        prim::st_f32v4(exp_avg4 + i, m);
247	        prim::st_f32v4(exp_avg_sq4 + i, v);
248	        prim::st_f32v4(s_track4 + i, st);
249	    }
250	}
