424	void launch_prodigy_dlr_reduce(
425	    torch::Tensor grad, torch::Tensor param, torch::Tensor param_init,
426	    torch::Tensor s, torch::Tensor numerator, torch::Tensor denominator,
427	    float eps
428	) {
429	    const int64_t N = grad.numel();
430	    if (N == 0) return;
431	    auto stream = at::cuda::getCurrentCUDAStream().stream();
432	    const int block = SG_TUNED_BLOCK_SIZE;
433	    const int grid = static_cast<int>(
434	        std::min<int64_t>(65535, (N + block - 1) / block));
435	    prodigy_dlr_reduce_kernel<<<grid, block, 0, stream>>>(
436	        grad.data_ptr<float>(), param.data_ptr<float>(),
437	        param_init.data_ptr<float>(), s.data_ptr<float>(),
438	        numerator.data_ptr<float>(), denominator.data_ptr<float>(),
439	        eps, N);
440	    SG_LAUNCH_CHECK(stream);
441	}
